message.content:
{
  "description": "The creature is shown in right-facing side profile standing on a plain light background. It has the overall body shape, fur, head and limbs of a shaggy brown goat, but its back is covered by a large domed turtle-like carapace and its shoulders, hips and lower legs are encased in matching hard, segmented scutes. The fur is long and coarse, dark brown on the neck, back and legs with a lighter cream underbelly, and the shell is patterned in dark brown, black and yellow-brown with raised, pyramidal scutes. All four legs end in cloven hooves and a short tufted tail is visible at the rear.",
  "parts": [
    {
      "part": "head",
      "looks_like": "goat-like with an elongated muzzle, dark nostril, dark eye with light iris, slightly open mouth, and a small beard of longer hair under the chin, covered in short brown fur",
      "where": "at the front end of the body on top of the neck, facing to the right"
    },
    {
      "part": "horns",
      "looks_like": "two thick, curved, ridged horns with concentric rings, dark brown to gray, tapering to points and sweeping backward",
      "where": "on top of the head behind the ears"
    },
    {
      "part": "ears",
      "looks_like": "two upright, pointed, fur-covered ears with visible inner ear detail",
      "where": "on the sides of the head just behind and below the horns"
    },
    {
      "part": "mane",
      "looks_like": "very thick, long, shaggy brown fur forming a mane-like ruff",
      "where": "along the underside and front of the neck extending down onto the chest"
    },
    {
      "part": "legs",
      "looks_like": "four sturdy, fur-covered goat-like legs, each with patches of hard, dark brown segmented armor encircling the upper and lower segments",
      "where": "under the body, two front legs beneath the chest and two hind legs beneath the hips"
    },
    {
      "part": "feet",
      "looks_like": "cloven hooves with two dark toes per foot and short fur immediately above the hoof",
      "where": "at the bottom ends of all four legs in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "short, shaggy tuft of brown and light brown fur",
      "where": "at the rear end of the body above the hind legs"
    },
    {
      "part": "shell",
      "looks_like": "large domed carapace made of polygonal scutes in mottled dark brown, black and yellow-brown, each scute with a raised pyramidal center and concentric growth lines",
      "where": "covering the dorsal surface from behind the shoulders to the rump, sitting on top of the fur"
    },
    {
      "part": "plates",
      "looks_like": "hard, turtle-shell-like segmented plates/scutes, dark brown with yellowish patterning and keeled, ridged texture, arranged in clusters",
      "where": "on the outer shoulders over the front legs, on the outer hips over the hind legs, and as bands encircling the lower portions of all four legs"
    },
    {
      "part": "scales",
      "looks_like": "the same hard scutes as the shell and leg plates, with concentric ringed texture and faceted surfaces",
      "where": "forming the entire shell on the back and the armor patches on the legs"
    },
    {
      "part": "markings",
      "looks_like": "shell and plate pattern of dark brown/black with irregular yellow-brown streaks; fur is darker brown on back and legs and creamy white on the belly",
      "where": "on the shell across the back and on the leg armor, and in the fur coloration of the body"
    }
  ],
  "attached_objects": [],
  "animals": ["goat", "turtle"],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
